namespace scratchbird::engine::internal_api { namespace { std::mutex m; std::map<std::string,scratchbird::engine::sblr::SblrKvStructuredReadDescriptorV1> live,used; std::string key(const scratchbird::engine::sblr::KvStructuredReadSha&h){return{reinterpret_cast<const char*>(h.data()),h.size()};} bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();} EngineApiDiagnostic d(std::string c,std::string k){return MakeEngineApiDiagnostic(std::move(c),std::move(k),{});} }
SblrKvStructuredReadCoordinationResult CompileSblrKvStructuredReadDescriptor(const EngineRequestContext&c,const std::string&r,std::uint64_t occurrence,std::uint32_t read_occurrence,std::uint64_t availability){std::lock_guard l(m);SblrKvStructuredReadCoordinationResult o;if(!tag(c,"private_kv_structured_read_binder")||!c.statement_metadata_snapshot_engine_owned||r!=c.statement_uuid.canonical||!occurrence||!read_occurrence||!availability){o.diagnostic=d("SBLR.OPERAND_INVALID","sblr.kv_structured_read.coordination_invalid");return o;}o.descriptor.body[0]=1;o.descriptor.body[1]=uint8_t(occurrence);o.descriptor.body[2]=uint8_t(read_occurrence);o.descriptor.availability=availability;auto b=scratchbird::engine::sblr::EncodeSblrKvStructuredReadDescriptorV1(o.descriptor,false);if(!scratchbird::engine::sblr::DecodeSblrKvStructuredReadDescriptorV1(b.data(),b.size(),&o.descriptor,nullptr,false)){o.diagnostic=d("SBLR.OPERAND_INVALID","sblr.kv_structured_read.descriptor_invalid");return o;}live[key(o.descriptor.evidence)]=o.descriptor;o.ok=true;o.diagnostic=d("OK","ok");return o;}
SblrKvStructuredReadCoordinationResult ConsumeSblrKvStructuredReadDescriptor(const EngineRequestContext&c,const scratchbird::engine::sblr::SblrKvStructuredReadDescriptorV1&v){std::lock_guard l(m);SblrKvStructuredReadCoordinationResult o;auto k=key(v.evidence);auto it=live.find(k);if(!tag(c,"private_kv_structured_read")){o.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.kv_structured_read.hidden");return o;}if(it==live.end()){o.diagnostic=used.count(k)?d("MGA.TRANSACTION.STALE","sblr.kv_structured_read.stale"):d("SECURITY.ACCESS_DENIED","sblr.kv_structured_read.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=d("PROCESS.CANCELLED","sblr.kv_structured_read.cancelled");return o;}used[k]=v;live.erase(it);o.ok=true;o.descriptor=v;o.diagnostic=d("OK","ok");return o;}}
